import {getParamFromUrl, setPathName} from '../../utils';

describe('This will test the path util functions.', () => {
  let oldLocation;
  let oldHistory;

  beforeEach(() => {
    oldLocation = window.location;
    delete (global as any).window.location;
    (global as any).window.location = new URL('http://www.unit-tests.com');

    oldHistory = window.history;
    delete (global as any).window.history;
    (global as any).window.history = {
      data: [],
      pushState: function(obj: { path: string}, unused: string, url: string): void {
        this.data.push({
          obj,
          unused,
          url
        });
      }
    };

  });

  afterEach(() => {
    window.location = oldLocation;
    window.history = oldHistory;
  });

  it('should test the getParamFromUrl function', () => {

    testIt('https://www.powerschool.com/', 'length', undefined);
    testIt('https://www.powerschool.com/', 'width', undefined);
    testIt('https://www.powerschool.com/length/500', 'length', '500');
    testIt('https://www.powerschool.com/length/500', 'width', undefined);
    testIt('https://www.powerschool.com/length/500/width/1000', 'length', '500');
    testIt('https://www.powerschool.com/length/500/width/1000', 'width', '1000');
    testIt('https://www.powerschool.com/calendar/length/500/width/1000', 'length', '500');
    testIt('https://www.powerschool.com/calendar/length/500/width/1000', 'width', '1000');


    function testIt(url: string, pathName: string, expectedResult: string | undefined): void {
      window.location.href = url;
      expect(getParamFromUrl(pathName)).toBe(expectedResult);
    }

  });

  it('should test setPathName function', () => {
    testIt('https://www.powerschool.com/', '', 'https://www.powerschool.com/');
    testIt('https://www.powerschool.com', '', 'https://www.powerschool.com/');
    testIt('https://www.powerschool.com/', 'calendar', 'https://www.powerschool.com/calendar');
    testIt('https://www.powerschool.com', 'calendar', 'https://www.powerschool.com/calendar');
    testIt('https://www.powerschool.com/', 'calendar/event/1234', 'https://www.powerschool.com/calendar/event/1234');
    testIt('https://www.powerschool.com', 'calendar/event/1234', 'https://www.powerschool.com/calendar/event/1234');
    testIt('https://www.powerschool.com/brians-page/', 'calendar/event/1234', 'https://www.powerschool.com/calendar/event/1234');
    testIt('https://www.powerschool.com/brians-page', 'calendar/event/1234', 'https://www.powerschool.com/calendar/event/1234');
    testIt('https://www.powerschool.com/brians-page/1/', 'calendar/event/1234', 'https://www.powerschool.com/calendar/event/1234');
    testIt('https://www.powerschool.com/brians-page/1', 'calendar/event/1234', 'https://www.powerschool.com/calendar/event/1234');

    function testIt(startUrl: string, pathName: string, expectedResult: string): void {
      window.location.href = startUrl;
      setPathName(pathName);
      const historyEntry = (window as any).history.data.at(-1);
      expect(new URL(historyEntry.obj.path).href).toBe(expectedResult);
      expect(new URL(historyEntry.url).href).toBe(expectedResult);
    }
  });

});